export function t(locale: UiLocale, key: string, values: Record<string, string | number> = {}): string {
  const template = copy[locale][key] || copy.fr[key] || key;
  return template.replace(/\{(\w+)\}/g, (_, name: string) => String(values[name] ?? ''));
}

export function languageDirection(locale: UiLocale): 'ltr' | 'rtl' {
  return locale === 'ar' ? 'rtl' : 'ltr';
}
